import {
  pgTable,
  text,
  timestamp,
  integer,
  boolean,
  jsonb,
  uuid,
} from "drizzle-orm/pg-core";

/**
 * Persisted record of a parsed NormalizedWorkflow.
 * The full normalized payload is stored as JSONB for flexible querying
 * while the top-level scalar fields are promoted to columns for indexing.
 */
export const workflows = pgTable("workflows", {
  /** UUIDv4 matching NormalizedWorkflow.id — generated by the parser. */
  id: uuid("id").primaryKey(),

  /** Source system enum value (GITHUB_ACTIONS, GITLAB_CI, etc.). */
  source: text("source").notNull(),

  /** Original file path in the repository (e.g. .github/workflows/ci.yml). */
  sourceFile: text("source_file").notNull(),

  /** Opaque repository identifier supplied at ingestion time. */
  repoId: text("repo_id").notNull(),

  /** UTC timestamp of when this workflow was parsed. */
  parsedAt: timestamp("parsed_at", { withTimezone: true }).notNull(),

  /** Total number of jobs — promoted from metadata for fast filtering. */
  totalJobs: integer("total_jobs").notNull().default(0),

  /** Total number of steps — promoted from metadata for fast filtering. */
  totalSteps: integer("total_steps").notNull().default(0),

  /** True if any secret reference was found in the workflow. */
  hasSecrets: boolean("has_secrets").notNull().default(false),

  /** True if any floating Docker image was found. */
  hasDockerImages: boolean("has_docker_images").notNull().default(false),

  /** True if any external (third-party) action was referenced. */
  hasExternalActions: boolean("has_external_actions").notNull().default(false),

  /** Full NormalizedWorkflow payload serialized as JSONB. */
  payload: jsonb("payload").notNull(),

  /** Row creation timestamp — set by the database. */
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

export type WorkflowRow = typeof workflows.$inferSelect;
export type NewWorkflowRow = typeof workflows.$inferInsert;
